from construire import Chapter,fig,box,qs,sub
from figures_communes import common,plot
from math import sqrt

def create():
 c=Chapter(2,"Signaux électriques dans l’ARQS","1.2","les grandeurs électriques, les dipôles linéaires, les lois de circuit et l’influence des appareils de mesure.")
 common(c)
 c.intro="Un voltmètre modifie-t-il la tension qu’il mesure ? Pourquoi un GBF ne fournit-il pas toujours la tension affichée ? Les lois de conservation et un petit nombre de modèles permettent de répondre, à condition de fixer les orientations avant de calculer."
 c.mapping=r'''Décrire le courant comme un débit de charge ; tester l’ARQS ; algébriser tensions, courants et puissances.\par Appliquer les lois des nœuds et des mailles. Modéliser les dipôles $R$, $C$, $L$ et une source de Thévenin ; calculer stockage et dissipation.\par Établir les associations de résistances et les diviseurs ; prévoir l’effet des résistances d’entrée et de sortie.'''
 c.prereq=r"Conversions ($\mathrm{mA}$, $\mathrm{k\Omega}$, $\mathrm{\mu F}$), équations linéaires, dérivée et intégrale simples. Le courant est algébrique ; sa flèche est une référence et ne préjuge pas du sens réel."
 c.method="Choisir une masse, nommer les nœuds, flécher chaque branche, écrire les lois locales puis les relations des dipôles. Ne simplifier le schéma qu’après avoir reconnu les vraies associations."
 c.boundary="Pages internes 13 et 14 de l’annexe de physique-chimie (pages PDF 50 et 51). Les régimes transitoires sont développés au chapitre 03."
 c.diagnostic=qs(r"Convertir $2{,}2\ \mathrm{k\Omega}$, $470\ \mathrm{nF}$ et $3{,}0\ \mathrm{mA}$ en unités SI.",r"Une charge de $12\ \mathrm{mC}$ traverse une section en $4{,}0\ \mathrm{s}$. Quel est le courant moyen ?",r"Si $V_A=5$ V et $V_B=-2$ V, calculer $u_{AB}$ et $u_{BA}$.",r"Deux résistances de $100\ \Omega$ sont en série, puis en parallèle. Donner les deux équivalents.",r"Une résistance reçoit $u=6$ V et est parcourue par $i=20$ mA en convention récepteur. Calculer sa puissance.",r"Quel branchement convient à un voltmètre ? À un ampèremètre ?",r"Que devient le courant d’un condensateur idéal en régime continu établi ? Et la tension d’une bobine idéale ?",r"Un fil de $1$ m transporte un signal à $2\times10^8$ m/s. Calculer le temps de propagation.")
 c.diag_sol=sub('D1 à D3',r"$2{,}2\times10^3\ \Omega$ ; $4{,}70\times10^{-7}$ F ; $3{,}0\times10^{-3}$ A. Le courant moyen vaut $\Delta q/\Delta t=3{,}0$ mA. $u_{AB}=V_A-V_B=7$ V et $u_{BA}=-7$ V.")+sub('D4 et D5',r"Série : $200\ \Omega$ ; parallèle : $50\ \Omega$. La puissance reçue est $p=ui=0{,}120$ W. Elle est positive avec les orientations annoncées.")+sub('D6 à D8',r"Le voltmètre se branche en dérivation ; l’ampèremètre s’insère en série. En continu établi, $\dot u_C=0$ donc $i_C=0$, et $\dot i_L=0$ donc $u_L=0$. Le temps de propagation est $5$ ns.")+box('methode','À reprendre en priorité',"Une confusion entre série et parallèle se traite en repérant les nœuds. Une erreur de puissance se traite en vérifiant les flèches, puis le signe du produit.")
 c.c('Charge, courant et échelles',r'''La charge électrique est quantifiée : $q=Ne$, avec $e=1{,}602\,176\,634\times10^{-19}$ C. À l’échelle d’un circuit usuel, le nombre de porteurs est immense : on décrit donc le transfert par une grandeur continue sans nier sa structure microscopique.
'''+box('loi','Un débit algébrique',r"$i(t)=\dd q/\dd t$, où $\dd q$ est la charge nette traversant une section dans le sens choisi pendant $\dd t$. Ainsi $\Delta q=\int i(t)\dd t$. Un courant négatif signifie que le transfert conventionnel se fait dans l’autre sens.")+fig('noeud','Les flèches définissent les courants algébriques ; elles n’imposent pas leurs signes.')+sub('Du microscopique au circuit',r"À $1$ mA, environ $6{,}24\times10^{15}$ charges élémentaires franchissent une section par seconde. Dans un métal, les électrons dérivent en sens opposé au courant conventionnel. La vitesse de dérive n’est pas la vitesse de propagation du signal.")+sub('Ordres de grandeur',r"Capteur : $\mathrm{\mu A}$ à $\mathrm{mA}$ ; petit montage électronique : quelques volts et $\mathrm{mA}$ ; démarreur automobile : centaines d’ampères. Le réseau domestique français est caractérisé par $230$ V efficaces et $50$ Hz ; ces valeurs décrivent un signal alternatif, pas sa valeur instantanée."))
 c.c('Quand peut-on utiliser l’ARQS ?',r'''Un signal met un temps $t_p=\ell/v$ pour parcourir un circuit de dimension caractéristique $\ell$. L’approximation des régimes quasi stationnaires néglige ce retard devant le temps caractéristique $T$ des variations étudiées.
'''+box('loi','Comparer deux durées',r"$\ell/v\ll T$. Pour un signal périodique de fréquence $f$, $\result{\ell f/v\ll1}$, soit $\ell\ll\lambda=v/f$. Utiliser la célérité dans le câblage ; $c$ fournit seulement une estimation dans le vide.")+sub('Exemple raisonné',r"Avec $\ell=1$ m, $v=2\times10^8$ m/s et $f=10$ kHz, le rapport vaut $5\times10^{-5}$ : le modèle de circuit localisé est cohérent. À $100$ MHz il vaut $0{,}5$ : les retards ne sont plus négligeables.")+box('piege','Les fronts rapides comptent',r"Un créneau de faible fréquence peut comporter des fronts très courts. Comparer aussi $\ell/v$ à la durée du front. Une fréquence de répétition seule ne garantit pas l’ARQS.")+sub('Ce que l’approximation permet',"On attribue une tension et un courant à chaque dipôle à un même instant. La charge accumulée dans les nœuds de connexion et les effets répartis du câblage sont négligés dans le modèle. Les capacités et inductances des composants restent, elles, explicitement prises en compte."))
 c.c('Potentiels, tensions et mailles',r'''On choisit un nœud de référence appelé masse et on lui attribue $V=0$. Les potentiels dépendent de cette référence ; les différences de potentiel n’en dépendent pas.
'''+box('loi','Une différence orientée',r"$u_{AB}=V_A-V_B$. La flèche de $u_{AB}$ va de $B$ vers $A$. Donc $u_{AB}=-u_{BA}$ et $u_{AB}+u_{BC}=u_{AC}$. Dans le modèle de circuit, la somme des tensions parcourues sur une maille est nulle.")+fig('thevenin','La flèche de u pointe vers la borne de potentiel utilisée en premier ; le courant de charge est descendant dans R.')+sub('Écrire une maille sans récitation',r"Partir du potentiel de la masse et suivre le circuit. Ici la source élève le potentiel de $E$, puis la résistance interne fait chuter le potentiel de $ri$ : $u=E-ri$. Dans la charge, $u=Ri$, d’où $i=E/(R+r)$.")+box('piege','Masse électrique et terre',"Une masse est une référence de potentiel. La terre est un conducteur de protection. Les masses des voies d’un oscilloscope de laboratoire sont souvent reliées entre elles et à la terre : vérifier la notice avant de connecter les pinces."))
 c.c('Conservation de la charge et nœuds',r'''Sur un petit volume entourant un nœud, le bilan de charge s’écrit $\dot q_{\rm nœud}=\sum i_{\rm entrants}-\sum i_{\rm sortants}$. Dans le modèle de nœud sans accumulation, le membre de gauche est négligeable.
'''+box('loi','Loi des nœuds',r"$\sum i_{\rm entrants}=\sum i_{\rm sortants}$. Les signes sont déterminés par les flèches, pas par les valeurs que l’on espère obtenir.")+fig('noeud','Un bilan de charge justifie la relation, même lorsqu’un courant calculé est négatif.')+sub('Exemple',r"Avec $i_1=4$ mA, $i_2=-1$ mA et $i_3=5$ mA, on obtient $i_4=i_1+i_2-i_3=-2$ mA. Le courant réel associé à $i_4$ circule vers le nœud.")+sub('Choisir les inconnues utiles',r"Pour $N$ nœuds, toutes les équations de nœud ne sont pas indépendantes : la somme des bilans s’annule. Fixer une masse puis rechercher les potentiels des autres nœuds limite les inconnues. Pour un nœud $V$ relié par $R_j$ aux potentiels connus $V_j$, écrire directement $\sum_j(V-V_j)/R_j=0$.")+box('methode','Vérifier après résolution',"Réinjecter les valeurs dans un nœud puis dans une maille non utilisée. Cette vérification détecte une inversion de courant ou une tension définie dans l’autre sens."))
 c.c('Puissance et conventions',r'''La puissance caractérise un transfert d’énergie par unité de temps. Son signe indique un sens d’échange relativement à la convention choisie ; un dipôle peut changer de rôle pendant une évolution.
'''+fig('conventions','La convention porte sur les flèches ; le fonctionnement dépend ensuite du signe de ui.')+box('loi','Énergie reçue et énergie fournie',r"En convention récepteur (flèches opposées), $p_{\rm reçue}=ui$. En convention générateur (flèches de même sens), $p_{\rm fournie}=ui$. L’énergie reçue entre $t_1$ et $t_2$ vaut $\int_{t_1}^{t_2}p_{\rm reçue}\dd t$.")+sub('Exemple : une batterie qui se recharge',r"En convention récepteur, $u=12$ V et $i=2$ A donnent $p=24$ W reçus. Si $i=-2$ A pour la même tension, la batterie fournit $24$ W. La flèche n’a pas changé ; le fonctionnement, lui, a changé.")+sub('Un contrôle global',r"Dans un circuit idéal sans stockage dans les fils, la somme des puissances reçues par tous les dipôles est nulle. Pour une source de Thévenin alimentant $R$ : $Ei=ri^2+Ri^2$. Le bilan sépare puissance produite par la source idéale, perte interne et puissance utile."))
 c.c('Résistances et associations',box('loi','Le conducteur ohmique',r"En convention récepteur : $u=Ri$, avec $R>0$ ; $\result{p_J=Ri^2=u^2/R\geq0}$. La conductance $G=1/R$ se mesure en siemens (S). Des résistances de montage vont couramment de quelques ohms à plusieurs mégohms ; leur puissance admissible doit être vérifiée.")+sub('Association série',r"Deux résistances sont en série si leur nœud commun ne possède aucune autre branche : elles portent le même courant. $u=(R_1+R_2)i$, donc $R_{\rm eq}=R_1+R_2$.")+sub('Association parallèle',r"Deux résistances sont en parallèle si elles relient exactement les mêmes nœuds : elles ont la même tension. $i=u/R_1+u/R_2$, donc $R_{\rm eq}=R_1R_2/(R_1+R_2)$. L’équivalent est plus petit que chacune des deux résistances.")+fig('diviseur','Le branchement de Re empêche de traiter R1 et R2 comme une simple série.')+box('methode','Tests limites',r"En parallèle, si $R_2\to\infty$, $R_{\rm eq}\to R_1$ ; si $R_2\to0$, $R_{\rm eq}\to0$. Ces limites valent mieux qu’une formule appliquée à un mauvais schéma."))
 c.c('Diviseurs de tension et de courant',box('loi','Deux résultats à démontrer',r"Deux résistances $R_1,R_2$ en série : $u_2=E\,R_2/(R_1+R_2)$. Deux résistances en parallèle recevant un courant total $I$ : $i_1=I\,R_2/(R_1+R_2)$ et $i_2=I\,R_1/(R_1+R_2)$.")+sub('Démonstration et sens physique',r"Pour le diviseur de tension, $i=E/(R_1+R_2)$ puis $u_2=R_2i$. Pour le diviseur de courant, $u=I/(1/R_1+1/R_2)$ puis $i_1=u/R_1$. La plus grande résistance reçoit la plus grande tension en série et le plus petit courant en parallèle.")+fig('diviseur','Pour la sortie chargée, remplacer R2 par R2 parallèle Re avant d’utiliser le diviseur.')+sub('Exemple chargé',r"$E=12$ V, $R_1=2\ \mathrm{k\Omega}$, $R_2=4\ \mathrm{k\Omega}$ : à vide $u=8$ V. Avec $R_e=4\ \mathrm{k\Omega}$, l’équivalent de sortie est $2\ \mathrm{k\Omega}$ et $u=6$ V. La baisse ne vient pas d’une modification de la source idéale mais de la redistribution des courants.")+box('piege','La condition fait partie de la formule',"Un diviseur de tension exige le même courant dans les deux résistances utilisées. Un diviseur de courant exige la même tension aux bornes des deux branches."))
 c.c('Condensateur : charge et énergie',r'''Le condensateur idéal est un modèle à deux armatures portant $q$ et $-q$. On oriente $u$ vers l’armature où entre le courant positif : c’est la convention récepteur.
'''+box('loi','Relations constitutives',r"$q=Cu$ ; $\result{i=C\dot u}$ ; $\result{\mathcal E_C=\tfrac12Cu^2}$. La capacité s’exprime en farads : dans les montages usuels, on rencontre souvent des pF, nF et $\mathrm{\mu F}$.")+fig('rc','Dans ce sens de i, la tension uC est orientée vers l’armature supérieure : i = C duC/dt.')+sub('Retrouver l’énergie',r"$p=ui=Cu\dot u=\dd(Cu^2/2)/\dd t$. L’énergie reçue par le composant idéal est stockée, puis peut être rendue. Le courant peut donc être de signe opposé à la tension.")+sub('Conséquences physiques',r"Une tension constante produit un courant nul : en continu établi, remplacer le condensateur idéal par un circuit ouvert. Si le courant reste fini, $u_C$ est continu ; un saut instantané demanderait un transfert impulsionnel de charge.")+box('methode','Exemple',r"$C=100\ \mathrm{nF}$ et $u=5$ V donnent $q=0{,}50\ \mathrm{\mu C}$ et $\mathcal E_C=1{,}25\ \mathrm{\mu J}$. Une rampe de pente $2\times10^3$ V/s impose $i=0{,}20$ mA."))
 c.c('Bobine : courant et énergie',box('loi','Bobine idéale en convention récepteur',r"$\result{u=L\dot i}$ ; $\result{\mathcal E_L=\tfrac12Li^2}$. L’inductance $L$ s’exprime en henrys. Dans un laboratoire d’enseignement : souvent mH à H ; la résistance du fil peut être significative.")+fig('rl','La tension uL est celle de l’inductance idéale. Une bobine réelle ajoute une résistance série r.')+sub('Stockage et continuité',r"$p=ui=Li\dot i=\dd(Li^2/2)/\dd t$. Avec une tension finie, le courant est continu. En continu établi, la tension de l’inductance idéale est nulle : elle devient un fil. La bobine réelle reste une résistance $r$ dans cette limite.")+sub('Exemple',r"$L=20$ mH et $i=0{,}10$ A donnent $\mathcal E_L=0{,}10$ mJ. Si le courant diminue de $0{,}10$ A en $1\ \mathrm{\mu s}$, l’ordre de grandeur de $|u|$ est $2$ kV. La rupture révèle les limites du modèle idéal et la nécessité d’un trajet de restitution d’énergie.")+box('piege','Ne pas confondre les deux continuités',r"C’est $u_C$ qui reste continu pour un courant fini ; c’est $i_L$ qui reste continu pour une tension finie. $i_C$ et $u_L$ peuvent changer brutalement lors d’une commutation idéale."))
 c.c('Source réelle et point de fonctionnement',box('loi','Modèle de Thévenin',r"Une source linéaire s’écrit $u=E-ri$ en convention générateur, avec $E$ sa tension à vide et $r$ sa résistance de sortie. La source idéale de tension correspond à $r=0$. Le modèle est valable dans le domaine où la caractéristique est affine.")+fig('thevenin','La droite de source et la loi de charge déterminent ensemble le point de fonctionnement.')+sub('Charge résistive',r"$u=Ri$, donc $i=E/(R+r)$ et $u=ER/(R+r)$. À vide ($R\to\infty$), $u\to E$ ; au court-circuit idéal, $i\to E/r$ si $r>0$. Ce dernier résultat est une prédiction du modèle et peut dépasser les limites réelles du générateur.")+sub('Mesurer sans court-circuiter',r"Mesurer $E$ avec un voltmètre de forte résistance, puis $u$ sur une résistance $R$ connue : $r=R(E/u-1)$. Choisir la charge dans le domaine autorisé du générateur.")+box('methode','Exemple GBF',r"Si $E=4{,}0$ V et $r=50\ \Omega$, une entrée $R=50\ \Omega$ reçoit $2{,}0$ V ; une entrée $1\ \mathrm{M\Omega}$ reçoit presque $4{,}0$ V. L’affichage peut être étalonné pour une charge donnée : lire le réglage et la notice."))
 c.c('Mesurer sans ignorer le montage',r'''Un voltmètre réel présente une résistance d’entrée $R_V$ ; un ampèremètre possède une résistance série $r_A$. Leur insertion change le circuit : il faut estimer cette perturbation avant de conclure.
'''+fig('diviseur','Le voltmètre se modélise par une résistance d’entrée en parallèle sur la sortie.')+box('loi','Adaptation en tension',r"Pour une source de résistance de sortie $R_s$ et une entrée $R_e$, $u=E\,R_e/(R_s+R_e)$. L’erreur relative de charge est $\varepsilon=R_s/(R_s+R_e)$. Pour $\varepsilon<1\,\%$, il faut $R_e>99R_s$.")+sub('Exemple de mesure',r"Une sortie équivalente à $E=5$ V, $R_s=100\ \mathrm{k\Omega}$ alimente un voltmètre $R_V=1\ \mathrm{M\Omega}$ : $u=4{,}545$ V et l’erreur vaut $9{,}09\,\%$. Avec $10\ \mathrm{M\Omega}$, elle descend à $0{,}990\,\%$.")+sub('Résistances typiques : vérifier la notice',r"Un GBF de laboratoire a souvent une sortie de $50\ \Omega$ ; un oscilloscope une entrée de $1\ \mathrm{M\Omega}$, parfois commutable en $50\ \Omega$ ; un multimètre numérique souvent $10\ \mathrm{M\Omega}$. Ce sont des modèles usuels, pas des garanties sur un appareil particulier.")+box('piege','Connexion des masses',"Les deux pinces de masse d’un oscilloscope de table ne permettent généralement pas de mesurer deux nœuds indépendants. Les placer sur des nœuds différents peut court-circuiter une partie du montage."))
 c.tp_title='Identifier une source réelle'
 c.tp=fig('thevenin','Mesurer u pour plusieurs résistances R connues ; calculer i = u/R.')+qs("Utiliser un générateur basse tension dans ses limites de courant. Choisir cinq charges et vérifier leurs puissances admissibles.",r"Mesurer la tension à vide, puis $u$ sur chaque charge ; calculer $i=u/R$. Répéter une mesure pour estimer la dispersion.",r"Ajuster $u=E-ri$ : l’ordonnée à l’origine donne $E$ et l’opposé de la pente donne $r$.",r"Comparer une charge de $50\ \Omega$ et une entrée de forte résistance ; expliciter le réglage de charge du GBF.","Tracer les résidus, discuter la résolution du voltmètre et la tolérance des charges.")+box('docu','Données simulées pour préparer l’exploitation',r"$R$ ($\Omega$) : $100$, $200$, $500$, $1000$.\par $u$ (V) : $4{,}00$, $4{,}80$, $5{,}45$, $5{,}71$.\par Elles correspondent approximativement à $E=6{,}0$ V et $r=50\ \Omega$. Elles ne sont pas des mesures réalisées.")+box('methode','Attendu du compte rendu',"Schéma orienté, tableau avec unités, estimation des incertitudes, droite ajustée, résidus et conclusion sur le domaine où le modèle de Thévenin décrit les résultats.")
 c.num_title='Un réseau résolu par les potentiels'
 c.num=r'''Deux nœuds $A$ et $B$ : $A$ est relié à $6$ V par $1\ \mathrm{k\Omega}$, à la masse par $2\ \mathrm{k\Omega}$ et à $B$ par $1\ \mathrm{k\Omega}$. $B$ est relié à la masse par $1\ \mathrm{k\Omega}$. Les bilans donnent :
\[2{,}5V_A-V_B=6,\qquad -V_A+2V_B=0.\]
\begin{verbatim}
import numpy as np
G = np.array([[2.5, -1.0], [-1.0, 2.0]])
b = np.array([6.0, 0.0])
VA, VB = np.linalg.solve(G, b)
print(VA, VB, G @ np.array([VA, VB]) - b)
\end{verbatim}
Ici les conductances ont été exprimées en mS ; les courants associés sont donc en mA. On trouve $V_A=3$ V et $V_B=1{,}5$ V.
'''+qs(r"Retrouver les équations de nœud avant d’exécuter le programme.",r"Calculer tous les courants puis vérifier que les puissances dissipées totalisent $18$ mW.",r"Remplacer la résistance $B$-masse par une très grande valeur et retrouver la limite $V_A=V_B=4$ V.","Faire varier une résistance et tracer la tension de sortie ; expliquer la tendance.")+box('piege','Le code vérifie le système écrit',"Un résidu numérique petit garantit que les équations saisies sont résolues. Il ne prouve pas qu’elles correspondent au schéma. La vérification physique reste nécessaire.")
 c.synthesis=box('loi','Les relations et leurs conditions',r"$i=\dot q$ ; ARQS : $\ell/v\ll T$ ; $u_{AB}=V_A-V_B$.\par Nœud sans accumulation : $\sum i_{\rm entrants}=\sum i_{\rm sortants}$.\par Récepteur : $p=ui$ ; $u_R=Ri$ ; $i_C=C\dot u_C$ ; $u_L=L\dot i_L$.\par $\mathcal E_C=Cu_C^2/2$ ; $\mathcal E_L=Li_L^2/2$ ; $p_J=Ri^2$.\par Thévenin : $u=E-ri$. Série : somme des résistances ; parallèle : somme des conductances.")+sub('Démonstrations à refaire',qs("Relier la loi des nœuds au bilan de charge.","Retrouver les deux diviseurs et leurs conditions.","Retrouver l’énergie d’un condensateur et d’une bobine à partir de la puissance.","Établir la chute de tension due à une résistance d’entrée finie."))+box('docu','Avant de rendre une copie',r"\checkline{Toutes les grandeurs ont une orientation.}\checkline{Les associations portent sur les bons nœuds.}\checkline{Les unités et les limites sont cohérentes.}\checkline{Le bilan des puissances est vérifié.}")
 c.td_titles=['Charges et approximations','Tensions et conservation','Puissance et composants','Simplifier un réseau','Diviser et mesurer','Sources et fonctionnement','Stocker et restituer','Raisonner sur un montage']
 entries=[
 ('Compter les porteurs',1,'8 min',qs(r"Un courant constant de $0{,}80$ mA circule pendant $2{,}0$ min. Calculer la charge transférée et le nombre de charges élémentaires ($e=1{,}60\times10^{-19}$ C).",r"Expliquer pourquoi une description continue est pertinente."),r"$\Delta q=i\Delta t=0{,}096$ C ; $N=\Delta q/e=6{,}0\times10^{17}$. Le transfert macroscopique comporte un très grand nombre de charges élémentaires."),
 ('Un courant variable',1,'10 min',qs(r"Pour $0\leq t\leq2$ s, $i(t)=3t^2$ mA, avec $t$ en secondes. Calculer la charge transférée et le courant moyen.","Le courant moyen est-il la demi-somme des valeurs extrêmes ?"),r"$\Delta q=\int_0^2 3t^2\dd t=8$ mC ; $I_{\rm moy}=4$ mA. La demi-somme des extrêmes vaut $6$ mA : elle ne donne pas la moyenne temporelle de cette fonction quadratique."),
 ('Tester l’ARQS',1,'10 min',qs(r"Un montage de $2$ m est utilisé à $100$ kHz, avec $v=2\times10^8$ m/s. Calculer $\ell f/v$.",r"Même question à $50$ MHz. Un front de $2$ ns est-il compatible avec le premier montage ?"),r"Les rapports valent $10^{-3}$ et $0{,}5$. Le premier cas est cohérent pour un signal sinusoïdal ; le second ne l’est pas. Le retard $10$ ns dépasse la durée du front : la faible fréquence de répétition ne suffit pas."),
 ('Changer de référence',1,'8 min',qs(r"$V_A=8$ V, $V_B=3$ V, $V_C=-1$ V. Calculer $u_{AB},u_{BC},u_{AC}$.",r"Prendre $B$ comme nouvelle masse et vérifier les tensions."),r"Les tensions valent $5$, $4$ et $9$ V. Après soustraction de $3$ V à tous les potentiels : $V'_A=5$ V, $V'_B=0$, $V'_C=-4$ V. Les trois différences restent identiques."),
 ('Le courant qui change de sens',1,'8 min',qs(r"Un nœud reçoit les courants fléchés $i_1=2$ mA et $i_2=-3$ mA ; $i_3=4$ mA et $i_4$ sont fléchés sortants. Déterminer $i_4$ et son sens réel."),r"$i_4=i_1+i_2-i_3=-5$ mA. Le courant réel associé entre dans le nœud avec une intensité de $5$ mA."),
 ('Une maille et son bilan',1,'12 min',qs(r"Une source $E=12$ V et $r=2\ \Omega$ alimente $R=10\ \Omega$. Calculer $i$, $u_R$ et les puissances.","Vérifier la conservation de l’énergie."),r"$i=12/(2+10)=1$ A, $u_R=10$ V. La source idéale fournit $12$ W ; $2$ W sont dissipés dans $r$ et $10$ W dans $R$. La somme des puissances reçues est nulle."),
 ('Le rôle d’une batterie',1,'10 min',qs(r"En convention récepteur, $u=12{,}0$ V et $i=-1{,}5$ A pendant $40$ s. Calculer la puissance reçue et l’énergie reçue. Identifier le fonctionnement."),r"$p=ui=-18$ W ; $W=-720$ J. La batterie fournit $18$ W et cède $720$ J. La convention récepteur reste celle des flèches."),
 ('Dimensionner une résistance',1,'10 min',qs(r"Une résistance $R=220\ \Omega$ supporte au plus $0{,}25$ W. Calculer les maxima de tension et de courant admissibles dans ce modèle."),r"$U_{\max}=\sqrt{RP_{\max}}=7{,}42$ V et $I_{\max}=\sqrt{P_{\max}/R}=33{,}7$ mA. La condition de puissance doit être satisfaite en plus des autres limites de la notice."),
 ('La pente crée le courant',1,'10 min',qs(r"Un condensateur de $2\ \mathrm{\mu F}$ reçoit une rampe de $-1$ à $5$ V en $3$ ms. Calculer le courant, la variation de charge et la variation d’énergie."),r"$\dot u=2000$ V/s donc $i=4$ mA ; $\Delta q=C\Delta u=12\ \mathrm{\mu C}$. $\Delta\mathcal E=C(25-1)/2=24\ \mathrm{\mu J}$. Le courant est constant pendant la rampe."),
 ('Deux associations',1,'10 min',qs(r"Calculer l’équivalent de $100\ \Omega$ en série avec le parallèle de $300\ \Omega$ et $600\ \Omega$.",r"Sous $12$ V, donner le courant total et les deux courants de dérivation."),r"Le parallèle vaut $200\ \Omega$, donc $R_{\rm eq}=300\ \Omega$. Le courant total est $40$ mA ; la tension du parallèle vaut $8$ V. Les courants valent $26{,}7$ et $13{,}3$ mA."),
 ('Un pont équilibré',2,'15 min',qs(r"Deux branches en parallèle sur $E=10$ V comportent respectivement $R_1=1\ \mathrm{k\Omega}$ au-dessus de $R_2=2\ \mathrm{k\Omega}$, et $R_3=3\ \mathrm{k\Omega}$ au-dessus de $R_4=6\ \mathrm{k\Omega}$. Donner les potentiels médians $V_A,V_B$.","Quel courant traverse une résistance reliant les milieux ?"),r"Chaque diviseur donne $V_A=V_B=20/3$ V. Le branchement entre milieux ne porte alors aucun courant. La condition générale est $R_2R_3=R_1R_4$."),
 ('Deux nœuds couplés',2,'18 min',qs(r"Reprendre le réseau de l’activité numérique : $A$ relié à $6$ V par $1$ k$\Omega$, à la masse par $2$ k$\Omega$, à $B$ par $1$ k$\Omega$ ; $B$ relié à la masse par $1$ k$\Omega$. Résoudre à la main et établir le bilan des puissances."),r"$2{,}5V_A-V_B=6$ et $2V_B-V_A=0$ donnent $V_A=3$ V et $V_B=1{,}5$ V. Courants : $3$, $1{,}5$, $1{,}5$, $1{,}5$ mA. Dissipations : $9+4{,}5+2{,}25+2{,}25=18$ mW, égales à $6\times3$ mW fournis."),
 ('Un diviseur chargé',2,'12 min',qs(r"$E=9$ V ; $R_1=3$ k$\Omega$ et $R_2=6$ k$\Omega$. Calculer la sortie à vide, puis avec $R_e=6$ k$\Omega$ en parallèle sur $R_2$."),r"À vide : $u=6$ V. En charge, $R_2\parallel R_e=3$ k$\Omega$, donc $u=4{,}5$ V. L’erreur relative à la tension à vide vaut $25\,\%$."),
 ('Un courant à partager',1,'10 min',qs(r"$I=12$ mA entre dans le parallèle de $R_1=1$ k$\Omega$ et $R_2=2$ k$\Omega$. Calculer les courants et la tension commune."),r"$i_1=I R_2/(R_1+R_2)=8$ mA ; $i_2=4$ mA ; $u=8$ V. Les courants se somment à $12$ mA et la branche la moins résistante porte le plus grand courant."),
 ('La résistance du voltmètre',2,'15 min',qs(r"Une sortie de Thévenin $E=3$ V, $R_s=100$ k$\Omega$ est mesurée par $R_V=900$ k$\Omega$. Donner la lecture et l’erreur relative.",r"Quel $R_V$ minimal faut-il pour une erreur au plus égale à $1\,\%$ ?"),r"$u=3\times900/1000=2{,}7$ V ; erreur $10\,\%$. $R_s/(R_s+R_V)\leq0{,}01$ impose $R_V\geq99R_s=9{,}9$ M$\Omega$."),
 ('Identifier Thévenin',2,'12 min',qs(r"Une source donne $6$ V à vide et $4$ V sur $100\ \Omega$. Identifier $E,r$ ; prédire la tension sur $200\ \Omega$."),r"$E=6$ V et $r=100(6/4-1)=50\ \Omega$. Sur $200\ \Omega$, $i=24$ mA et $u=4{,}8$ V. Une seconde charge permet de tester la validité du modèle."),
 ('Le GBF et sa terminaison',2,'12 min',qs(r"Un GBF est modélisé par $E=8$ V et $r=50\ \Omega$. Calculer la tension sur une entrée $50\ \Omega$, puis $1$ M$\Omega$.","Quel facteur relie approximativement les lectures ?"),r"$u_{50}=4$ V ; $u_{1\rm M}=7{,}9996$ V. Le facteur est presque $2$. Il dépend de la résistance de charge et de l’étalonnage de l’affichage."),
 ('Puissance utile maximale',2,'20 min',qs(r"Pour une source $(E,r)$ chargée par $R>0$, établir $P_R=E^2R/(R+r)^2$ et déterminer son maximum.",r"Calculer le rendement $P_R/(Ei)$ au maximum."),r"$P'_R=E^2(r-R)/(R+r)^3$ : maximum pour $R=r$, égal à $E^2/(4r)$. À ce point $P_R=ri^2$, donc le rendement vaut $1/2$. Maximiser la puissance utile ne maximise pas ce rendement."),
 ('Décharger une capacité',2,'12 min',qs(r"Un condensateur $C=10\ \mathrm{\mu F}$ passe de $8$ V à $2$ V. Calculer la variation d’énergie et la charge algébrique reçue par l’armature de référence."),r"$\Delta\mathcal E=\tfrac12C(2^2-8^2)=-300\ \mathrm{\mu J}$. $\Delta q=C(2-8)=-60\ \mathrm{\mu C}$. La capacité rend de l’énergie, indépendamment du détail temporel."),
 ('Une bobine réelle',2,'12 min',qs(r"Une bobine de $L=50$ mH et de résistance $r=10\ \Omega$ reçoit $i=0{,}2$ A constant. Donner sa tension, sa puissance dissipée et son énergie magnétique."),r"La partie inductive a une tension nulle ; la bobine réelle a $u=ri=2$ V. $p_J=ri^2=0{,}4$ W et $\mathcal E_L=Li^2/2=1$ mJ. Une énergie stockée constante n’implique pas une consommation nulle pour le dipôle réel."),
 ('Rendre un courant continu',2,'15 min',qs(r"Dans un circuit comportant $E=12$ V, une résistance $100\ \Omega$ et une bobine $(L,r=20\ \Omega)$ en série, donner le courant final. Un condensateur idéal en parallèle sur la bobine modifie-t-il ce courant final ?"),r"En continu établi, remplacer $L$ par un fil et $C$ par un circuit ouvert. Le courant est $12/(100+20)=0{,}10$ A. Le condensateur ne change pas cette valeur finale ; sa tension finale est $2$ V."),
 ('Mesurer une résistance',3,'20 min',qs(r"Un voltmètre $R_V=1$ M$\Omega$ mesure la tension aux bornes de $R=100$ k$\Omega$. L’ampèremètre en amont mesure la somme des courants de $R$ et du voltmètre. Quelle résistance apparente $U/I$ obtient-on ? Comment corriger ?"),r"$R_{\rm app}=R\parallel R_V=90{,}91$ k$\Omega$. L’erreur est $-9{,}09\,\%$. $1/R=1/R_{\rm app}-1/R_V$ permet de retrouver $R$."),
 ('Une échelle répétée',3,'25 min',qs(r"Une cellule comprend une résistance $R$ en série, puis une résistance $R$ en parallèle avec la suite du réseau. Écrire la récurrence de $X_n$ si $X_1=2R$.",r"En admettant la convergence, trouver la limite positive pour $R=1$ k$\Omega$."),r"$X_n=R+RX_{n-1}/(R+X_{n-1})$. À la limite, $X^2-RX-R^2=0$ ; la racine positive est $X=(1+\sqrt5)R/2=1{,}618$ k$\Omega$. La racine négative est incompatible avec un réseau de résistances positives."),
 ('Un résultat avec incertitude',3,'20 min',qs(r"Une source est identifiée par $r=R(E/u-1)$ avec $R=100\ \Omega$, $E=6{,}00$ V, $u=4{,}00$ V. On suppose $R$ exact et les tensions indépendantes, d’incertitudes-types $u(E)=u(u)=0{,}01$ V. Calculer $r$ et son incertitude au premier ordre."),r"$r=50\ \Omega$. $\partial r/\partial E=R/u=25\ \Omega$/V ; $\partial r/\partial u=-RE/u^2=-37{,}5\ \Omega$/V. $u(r)=\sqrt{0{,}25^2+0{,}375^2}=0{,}451\ \Omega$. Présentation possible : $r=50{,}0\ \Omega$, $u(r)=0{,}5\ \Omega$. Une erreur commune aux deux lectures invaliderait l’indépendance.")]
 for e in entries:c.e(*e)
 c.d('Un pont qui révèle un capteur',r'''Deux branches sont alimentées par $E$ entre le nœud haut et la masse. À gauche : $R$ en haut et $R(1+\varepsilon)$ en bas ; à droite : deux résistances $R$. Le voltmètre relie leurs milieux $A$ et $B$ et possède une résistance $R_V$.
'''+qs(r"À vide, exprimer $u_{AB}$ puis son équivalent au premier ordre en $\varepsilon$.",r"Justifier que la résistance de sortie entre $A$ et $B$ vaut $R_s=(R\parallel R(1+\varepsilon))+R/2$ lorsque la source idéale est remplacée par un fil.",r"En déduire la lecture en charge. Pour $E=5$ V, $R=1$ k$\Omega$, $\varepsilon=0{,}02$, $R_V=100$ k$\Omega$, chiffrer l’erreur de charge.","Quelle grandeur doit-on rendre petite pour mesurer une faible variation ?"),"1. Les deux milieux sont des diviseurs à vide. 2. Éteindre une source idéale de tension revient à court-circuiter ses bornes. 3. Traiter le voltmètre comme la charge de l’équivalent de sortie.",r'''À vide, $V_A=E(1+\varepsilon)/(2+\varepsilon)$ et $V_B=E/2$, donc
\[u_0=\frac{E\varepsilon}{2(2+\varepsilon)}\simeq\frac{E\varepsilon}{4}.\]
La source idéale annulée relie le nœud haut à la masse. Chaque milieu voit ses deux résistances en parallèle ; entre milieux, les deux équivalents s’ajoutent. Ainsi $R_s=R(1+\varepsilon)/(2+\varepsilon)+R/2$.
\[u_{\rm lu}=u_0\frac{R_V}{R_V+R_s}.\]
On trouve $u_0=24{,}752$ mV, $R_s=1004{,}95\ \Omega$, $u_{\rm lu}=24{,}506$ mV ; l’erreur de charge vaut $0{,}995\,\%$. L’approximation au premier ordre donne $25$ mV : son erreur doit aussi être distinguée de la perturbation par le voltmètre.
'''+box('methode','Ce que le résultat apprend',r"La sensibilité à vide vaut environ $E/4$ volt par unité de $\varepsilon$. Une forte résistance d’entrée limite la perturbation, mais ne supprime ni l’erreur du capteur ni l’imprécision de lecture."))
 c.d('Alimenter : puissance ou rendement ?',qs(r"Une source $(E,r)$ doit fournir au moins $P_0$ à une charge résistive $R$. Poser $x=R/r$ et $\beta=P_0r/E^2$. Écrire l’inégalité à résoudre.",r"Déterminer les valeurs admissibles de $x$ et la condition d’existence.",r"Pour $E=12$ V, $r=2\ \Omega$ et $P_0=10$ W, calculer l’intervalle de $R$ et choisir la résistance donnant le meilleur rendement.","Justifier le compromis obtenu avec la tension de sortie."),"1. Écrire la puissance en fonction de x. 2. Le maximum de x/(1+x)² vaut 1/4. 3. Le rendement x/(1+x) est croissant.",r'''$P_R=(E^2/r)x/(1+x)^2$. La contrainte devient $\beta x^2+(2\beta-1)x+\beta\leq0$. Elle admet des solutions si $0<\beta\leq1/4$ ; les bornes sont
\[x_\pm=\frac{1-2\beta\pm\sqrt{1-4\beta}}{2\beta}.\]
Ici $\beta=5/36$ ; $R_-=0{,}4\ \Omega$ et $R_+=10\ \Omega$. Le rendement $\eta=x/(1+x)$ augmente avec $R$ : choisir $R=10\ \Omega$ donne $i=1$ A, $u=10$ V, $P_R=10$ W et $\eta=5/6$. À l’autre borne, $i=5$ A, $u=2$ V et le rendement vaut $1/6$.
'''+box('piege','Le maximum ne répond pas à toute question',r"La puissance maximale $18$ W est atteinte à $R=2\ \Omega$, mais le rendement y vaut seulement $1/2$. Le cahier des charges doit annoncer la grandeur à optimiser."))
 c.d('Deux mesures pour une source',qs(r"Une source de Thévenin alimente successivement $R_1$ et $R_2$, donnant $u_1$ et $u_2$. Établir une relation affine entre $1/u$ et $1/R$.",r"Avec $R_1=100\ \Omega$, $u_1=4$ V, $R_2=200\ \Omega$, $u_2=4{,}8$ V, retrouver $E,r$ sans mesure à vide.",r"Comment une troisième mesure teste-t-elle le modèle ? Pourquoi deux charges presque égales rendent-elles l’estimation fragile ?"),"1. Inverser u = ER/(R+r). 2. La pente donne r/E et l’ordonnée 1/E. 3. Examiner le dénominateur qui sépare les deux mesures.",r'''$1/u=1/E+(r/E)(1/R)$. La pente entre les points vaut $(0{,}25-0{,}20833)/(0{,}01-0{,}005)=8{,}3333\ \Omega$/V, et l’ordonnée vaut $1/6$ V$^{-1}$. Donc $E=6$ V et $r=50\ \Omega$.
\[r=\frac{u_2-u_1}{u_1/R_1-u_2/R_2},\qquad E=u_1(1+r/R_1).\]
Une troisième mesure doit se placer sur la droite, dans les incertitudes. Des charges proches donnent des courants proches : l’estimation de la pente résulte alors de la différence de deux lectures voisines, sensible au bruit. Les charges doivent rester dans le domaine linéaire et respecter les limites de courant et de puissance.
'''+box('methode','Choisir les mesures',"Écarter suffisamment les courants, répéter les lectures et examiner les résidus. Une droite ajustée n’est convaincante que si l’échelle des écarts est comparée à celle des incertitudes."))
 c.dm_title='Une sortie de capteur à mesurer'
 c.dm=fig('diviseur','E = 10 V ; R1 = 10 kΩ ; R2 = 20 kΩ ; Re est la résistance du voltmètre.')+qs(r"Calculer la tension de sortie à vide. \textbf{3 points}",r"Établir son modèle de Thévenin : $E_s$ et $R_s$. Justifier la résistance équivalente. \textbf{4 points}",r"Pour $R_V=100$ k$\Omega$, donner la lecture et l’erreur relative. \textbf{3 points}",r"Déterminer $R_V$ minimal pour une erreur de charge au plus égale à $0{,}5\,\%$. \textbf{3 points}",r"Le voltmètre indique $6{,}24$ V avec $R_V=100$ k$\Omega$. Corriger cette lecture pour estimer la tension à vide. \textbf{3 points}",r"Proposer un protocole pour tester le modèle de sortie et citer deux limites. \textbf{4 points}")
 c.dm_sol=sub('1 et 2 / 7 points',r"$E_s=10\times20/(10+20)=20/3$ V (3 points). Source idéale éteinte, les deux résistances relient la sortie à la masse en parallèle : $R_s=R_1R_2/(R_1+R_2)=20/3$ k$\Omega$ (schéma et justification 2 ; valeur 2).")+sub('3 et 4 / 6 points',r"$u=E_sR_V/(R_s+R_V)=6{,}25$ V ; $\varepsilon=6{,}25\,\%$ (3 points). $R_V\geq(1/0{,}005-1)R_s=1{,}327$ M$\Omega$ (inégalité 2 ; résultat 1).")+sub('5 / 3 points',r"$E_{\rm estimé}=u(1+R_s/R_V)=6{,}656$ V. La correction suppose que $R_s$ et $R_V$ sont connus ; elle ne supprime pas l’incertitude de lecture.")+sub('6 / 4 points',"Mesurer plusieurs charges connues et ajuster la tension en fonction du courant (2). Examiner la dispersion, la tolérance des résistances, l’entrée du voltmètre et le domaine linéaire (deux limites expliquées : 2).")
 c.ds_title='Alimenter, diviser et stocker'
 c.ds=[sub('Partie A / Source réelle / 8 points',r"Une source donne $U_0=12$ V à vide et $U_1=10$ V sur $R=100\ \Omega$.")+qs(r"Identifier le modèle de Thévenin, en justifiant chaque paramètre. \textbf{3 points}",r"Pour une charge $80\ \Omega$, calculer courant et tension. \textbf{2 points}",r"Établir le bilan des puissances sur cette charge. \textbf{2 points}",r"Énoncer la condition d’ARQS pour un circuit de taille $\ell$ et un signal de fréquence $f$. \textbf{1 point}")+sub('Partie B / Diviseur chargé / 7 points',r"Une source idéale de $9$ V alimente $R_1=3$ k$\Omega$ en série avec $R_2=6$ k$\Omega$ ; la sortie est prise sur $R_2$.")+qs(r"Donner la sortie à vide et justifier le diviseur. \textbf{2 points}",r"On branche $R_e=6$ k$\Omega$ sur la sortie. Calculer la nouvelle tension et tous les courants. \textbf{3 points}",r"Quelle résistance d’entrée minimale limite la baisse à $1\,\%$ de la sortie à vide ? \textbf{2 points}"),sub('Partie C / Stockage et conventions / 5 points',r"Un condensateur $C=4$ $\mathrm{\mu F}$ reçoit une tension passant linéairement de $2$ V à $8$ V en $6$ ms. Une bobine idéale de $L=100$ mH porte un courant $0{,}20$ A.")+qs(r"Calculer le courant du condensateur avec des orientations explicites. \textbf{2 points}",r"Calculer l’énergie reçue par le condensateur durant la rampe. \textbf{1 point}",r"Calculer l’énergie magnétique et estimer la tension si le courant de bobine tombe à zéro en $10\ \mathrm{\mu s}$. Interpréter le signe en convention récepteur. \textbf{2 points}")]
 c.ds_sol=[sub('A / 8 points',r"$E=12$ V et $r=100(12/10-1)=20\ \Omega$ (3). Pour $R=80\ \Omega$, $i=0{,}12$ A, $u=9{,}6$ V (2). $Ei=1{,}44$ W, $ri^2=0{,}288$ W, $Ri^2=1{,}152$ W : le bilan se ferme (2). ARQS : $\ell f/v\ll1$ (1).")+sub('B / 7 points',r"À vide $u_0=6$ V car les résistances portent le même courant (2). En charge $R_2\parallel R_e=3$ k$\Omega$, $u=4{,}5$ V, courant dans $R_1$ : $1{,}5$ mA, dans chaque branche basse : $0{,}75$ mA (3). La sortie a $R_s=R_1\parallel R_2=2$ k$\Omega$ ; $R_e\geq99R_s=198$ k$\Omega$ (2)."),sub('C / 5 points',r"En convention récepteur, $i=C\dot u=4$ mA (orientation 1 ; calcul 1). $\Delta\mathcal E_C=C(8^2-2^2)/2=120\ \mathrm{\mu J}$ (1). $\mathcal E_L=Li^2/2=2$ mJ ; la pente vaut $-2\times10^4$ A/s et $u_L=-2000$ V (1). Le signe négatif avec $i>0$ indique que la bobine fournit de l’énergie ; le modèle idéal prévoit une très forte surtension et ses limites doivent être considérées (1).")+box('methode','Correction par capacité',"Une erreur de signe impose de revoir le schéma orienté. Une mauvaise lecture du diviseur impose de redessiner les nœuds. Une confusion entre énergie et puissance se corrige en vérifiant leurs unités : J et W.")]
 c.hints="E11 : comparer les potentiels médians. E12 : choisir les potentiels comme inconnues. E18 : dériver la puissance, puis calculer séparément le rendement. E23 : remplacer la suite de l’échelle par son équivalent. E24 : propager les deux incertitudes avec les dérivées partielles."
 c.eval_hints="Le DM se ramène à une source de sortie chargée par le voltmètre. Dans le DS, commencer chaque partie avec ses données propres ; les sources des parties A et B sont différentes."
 c.source('DM réel / Réseau de résistances','https://mpsi.schleck.ovh/fichiers/devoirs/dm2_optique_elec.pdf','MPSI, schleck.ovh ; DM2 à rendre le 29 septembre 2026 ; exercice 2, questions 1 à 6, page 2/2.',"Prévoir 35 minutes. Résoudre d’abord la cellule isolée, puis construire la récurrence du réseau. Garder le dessin original : chaque cellule comporte deux résistances R sur les rails et une branche transversale 2R.",r"La cellule isolée est une série $R+2R+R=4R$. La résistance du bas reçoit $u_R=E/4=1{,}5$ V. Sa puissance vaut $E^2/(16R)=2{,}25$ mW ; la source fournit $E^2/(4R)=9$ mW, d’où $\eta=1/4$. La récurrence est $X_n=2R+2RX_{n-1}/(2R+X_{n-1})$ ; $X_1=4R$ et $X_2=10R/3$. La limite positive vérifie $X^2-2RX-4R^2=0$, soit $X=(1+\sqrt5)R=3{,}236$ k$\Omega$. Ces résultats concernent le schéma du DM, différent de E23.")
 c.source('DS réel / Panneau solaire','https://mpsi.schleck.ovh/fichiers/devoirs/ds02_enonce.pdf','MPSI, schleck.ovh ; DS2 du 8 octobre 2026 ; partie III, questions 1 et 4 à 6, pages 5/7 et 6/7.',"Prévoir 30 minutes. Lire la caractéristique réelle avant de travailler le modèle local de Thévenin. Pour les questions 4 à 6, prendre x branches en parallèle et y cellules par branche, avec xy=N.",r"Une courbe d’iso-puissance vérifie $I=P/U$. Les branches donnent $E_{\rm eq}=yE=NE/x$ et $r_{\rm eq}=yr/x=Nr/x^2$, donc $U=NExR/(Rx^2+Nr)$. Dans l’optimisation continue, $x=\sqrt{Nr/R}$ et $y=\sqrt{NR/r}$ : l’adaptation donne $P_{\max}=NE^2/(4r)$ et $P_J=P_{\max}$. Le câblage réel impose des entiers et des diviseurs de N : comparer les configurations réalisables.")
 c.next="Le chapitre 03 étudie l’évolution temporelle des circuits RC et RL. Les relations des dipôles deviennent des équations différentielles ; les continuités permettent d’en fixer les conditions initiales."
 for name,a,b in [('E01-q',.0008*120,.096),('E02-q',3*8/3,8),('E06-i',12/12,1),('E08-U',sqrt(220*.25),7.416198487095663),('E09-énergie',.5*2e-6*(25-1),24e-6),('E10-Req',100+300*600/900,300),('E13-u',9*3000/6000,4.5),('E15-seuil',99*1e5,9.9e6),('E16-r',100*(6/4-1),50),('E18-max',12**2/(4*2),18),('E19-énergie',.5*1e-5*(4-64),-3e-4),('E20-stock',.5*.05*.2**2,.001),('E22-apparent',1e5*1e6/1.1e6,90909.09090909091),('E23-limite',(1+sqrt(5))/2,1.618033988749895),('E24-incertitude',sqrt(.25**2+.375**2),.45069390943299864),('D2-Rplus',2*5,10),('DS-énergieC',.5*4e-6*60,.00012),('DS-surtension',.1*(-.2/1e-5),-2000),('R1-cellule',1+2+1,4),('R1-eta',.00225/.009,.25)]:c.check(name,a,b)
 return c
